import random, copy, time
import numpy as np
from scipy import sparse
from reference import Task

def solver_variant(tol=0, maxiter=None, ncv=20):
    def solve(problem):
        A=problem['matrix']; k=problem['k']; N=A.shape[0]
        v0=np.ones(N, dtype=A.dtype)
        vals, vecs = sparse.linalg.eigs(A,k=k,v0=v0,tol=tol,maxiter=maxiter,ncv=ncv)
        pairs=list(zip(vals, vecs.T)); pairs.sort(key=lambda p:-abs(p[0]))
        return [v for _,v in pairs]
    return solve

def evaluate(solve, trials=100):
    task=Task()
    for seed in random.sample(range(1_000_000), trials):
        prob=task.generate_problem(n=300, random_seed=seed)
        sol=solve(copy.deepcopy(prob))
        if not task.is_solution(prob, sol):
            return False, seed
    return True, None

for ncv in [20]:
    for maxiter in [None, 500, 1000, 2000]:
        ok,fail_seed=evaluate(solver_variant(0,maxiter,ncv), trials=30)
        print('ncv',ncv,'maxiter',maxiter,'ok',ok,fail_seed)
